// Development-only observer of the actual SDK's slice::sort_by. Standard sort
// bodies are neither rewritten nor replaced. Python retains SHA256 commitments
// to every callback, final slot and destructor event emitted below.
#![feature(freeze)]
use std::{cell::{Cell,RefCell},io::{self,Write},marker::Freeze,panic::{catch_unwind,AssertUnwindSafe}};
thread_local! {static DROPS:RefCell<Vec<u64>>=const{RefCell::new(Vec::new())};}
trait Value {fn key(&self)->i64;fn id(&self)->u64;fn touches(&self)->u64{0}fn touch(&self){} }
#[repr(C)]#[derive(Copy,Clone)]struct Frozen<const PAD:usize>{key:i64,id:u64,padding:[u8;PAD]}
impl<const PAD:usize>Value for Frozen<PAD>{fn key(&self)->i64{self.key}fn id(&self)->u64{self.id}}
#[repr(C)]struct Mutable{key:i64,id:u64,touches:Cell<u64>}
impl Value for Mutable{fn key(&self)->i64{self.key}fn id(&self)->u64{self.id}fn touches(&self)->u64{self.touches.get()}fn touch(&self){self.touches.set(self.touches.get()+1)}}
impl Value for &Mutable{fn key(&self)->i64{(**self).key()}fn id(&self)->u64{(**self).id()}fn touches(&self)->u64{(**self).touches()}fn touch(&self){(**self).touch()}}
impl Value for (&Mutable,&Mutable){fn key(&self)->i64{self.0.key()}fn id(&self)->u64{self.0.id()}fn touches(&self)->u64{self.0.touches()+self.1.touches()}fn touch(&self){self.0.touch();self.1.touch()}}
#[repr(C)]struct Dropped{key:i64,id:u64}
impl Value for Dropped{fn key(&self)->i64{self.key}fn id(&self)->u64{self.id}}
impl Drop for Dropped{fn drop(&mut self){DROPS.with(|d|d.borrow_mut().push(self.id));}}
#[derive(Copy,Clone)]struct Zero;
impl Value for Zero{fn key(&self)->i64{0}fn id(&self)->u64{0}}
fn prove<T:Freeze+Copy>(){}
fn random(state:&mut u64)->u64{*state^=*state<<13;*state^=*state>>7;*state^=*state<<17;*state}
fn initial(length:usize,seed:u64,distribution:usize)->Vec<(i64,u64)>{let mut state=seed;let mut values=Vec::new();for id in 0..length{let bits=random(&mut state);let key=match distribution{0=>(bits%13)as i64,1=>(bits%100003)as i64,2=>id as i64,3=>(length-id)as i64,4=>17,5=>id.min(length-id)as i64,6=>((id/31)*31+(bits%5)as usize)as i64,_=>unreachable!()};values.push((key,id as u64));}values}
fn hex(bytes:&[u8])->String{let mut out=String::with_capacity(bytes.len()*2);const H:&[u8]=b"0123456789abcdef";for &b in bytes{out.push(H[(b>>4)as usize]as char);out.push(H[(b&15)as usize]as char);}out}
fn word(out:&mut Vec<u8>,value:u64){out.extend_from_slice(&value.to_le_bytes())}
fn observe<T:Value>(mut values:Vec<T>,mode:usize,fail:isize)->(bool,usize,Vec<u8>,Vec<u8>,Vec<u8>,String){let mut trace=Vec::new();let mut calls=0;DROPS.with(|d|d.borrow_mut().clear());let panic=catch_unwind(AssertUnwindSafe(||values.sort_by(|a,b|{a.touch();b.touch();word(&mut trace,a.id());word(&mut trace,b.id());word(&mut trace,a.touches());word(&mut trace,b.touches());word(&mut trace,std::ptr::eq(a,b)as u64);let index=calls;calls+=1;if index as isize==fail{std::panic::panic_any("comparison_failure")};match mode{0=>a.key().cmp(&b.key()),1=>std::cmp::Ordering::Less,2=>{let a=a.key()%3;let b=b.key()%3;if a==b{std::cmp::Ordering::Equal}else if (a+1)%3==b{std::cmp::Ordering::Less}else{std::cmp::Ordering::Greater}},3=>if index%2==0{a.key().cmp(&b.key())}else{b.key().cmp(&a.key())},_=>unreachable!()}}))).err();let mut state=Vec::new();for v in &values{word(&mut state,v.id());word(&mut state,v.key()as u64);word(&mut state,v.touches());}drop(values);let mut drops=Vec::new();DROPS.with(|d|for &id in d.borrow().iter(){word(&mut drops,id)});let message=panic.as_ref().map(|p|if let Some(s)=p.downcast_ref::<&str>(){(*s).to_owned()}else if let Some(s)=p.downcast_ref::<String>(){s.clone()}else{"other_panic".into()}).unwrap_or_default();(panic.is_some(),calls,trace,state,drops,message)}
fn run(kind:usize,length:usize,seed:u64,distribution:usize,mode:usize,fail:isize)->(usize,usize,bool,bool,(bool,usize,Vec<u8>,Vec<u8>,Vec<u8>,String)){let input=initial(length,seed,distribution);macro_rules! frozen{($p:expr)=>{{prove::<Frozen<$p>>();let v=input.into_iter().map(|(key,id)|Frozen::<$p>{key,id,padding:[0;$p]}).collect();(size_of::<Frozen<$p>>(),align_of::<Frozen<$p>>(),true,true,observe(v,mode,fail))}}}match kind{0=>frozen!(0),1=>frozen!(8),2=>frozen!(48),3=>frozen!(240),4=>{let v=input.into_iter().map(|(key,id)|Mutable{key,id,touches:Cell::new(0)}).collect();(size_of::<Mutable>(),align_of::<Mutable>(),false,false,observe(v,mode,fail))},5|6=>{let owners:Vec<_>=input.into_iter().map(|(key,id)|Mutable{key,id,touches:Cell::new(0)}).collect();if kind==5{prove::<&Mutable>();let v=owners.iter().collect();(size_of::<&Mutable>(),align_of::<&Mutable>(),true,true,observe(v,mode,fail))}else{prove::<(&Mutable,&Mutable)>();let others:Vec<_>=owners.iter().map(|v|Mutable{key:v.key,id:v.id,touches:Cell::new(0)}).collect();let v=owners.iter().zip(others.iter()).collect();(size_of::<(&Mutable,&Mutable)>(),align_of::<(&Mutable,&Mutable)>(),true,true,observe(v,mode,fail))}},7=>{let v=input.into_iter().map(|(key,id)|Dropped{key,id}).collect();(size_of::<Dropped>(),align_of::<Dropped>(),true,false,observe(v,mode,fail))},8=>frozen!(4080),9=>{prove::<Zero>();(size_of::<Zero>(),align_of::<Zero>(),true,true,observe(vec![Zero;length],mode,fail))},_=>unreachable!()}}
fn emit(out:&mut impl Write,kind:usize,length:usize,seed:u64,distribution:usize,mode:usize,fail:isize)->io::Result<usize>{let(size,align,freeze,copy,(panic,calls,trace,state,drops,message))=run(kind,length,seed,distribution,mode,fail);writeln!(out,"{kind}\t{length}\t{seed}\t{distribution}\t{mode}\t{fail}\t{size}\t{align}\t{freeze}\t{copy}\t{panic}\t{calls}\t{}\t{}\t{}\t{}",hex(&trace),hex(&state),hex(&drops),hex(message.as_bytes()))?;Ok(calls)}
fn case(out:&mut impl Write,kind:usize,length:usize,seed:u64,distribution:usize,mode:usize)->io::Result<()>{let calls=emit(out,kind,length,seed,distribution,mode,-1)?;let mut cuts=if length<=33{(0..=calls+1).collect::<Vec<_>>()}else{vec![0,1,2,3,7,calls/2,calls.saturating_sub(1),calls,calls+1]};cuts.sort_unstable();cuts.dedup();for fail in cuts{emit(out,kind,length,seed,distribution,mode,fail as isize)?;}Ok(())}
fn main()->io::Result<()>{std::panic::set_hook(Box::new(|_|{}));let mut out=io::BufWriter::new(io::stdout().lock());for kind in 0..9{for seed in [1,7]{for length in [0,1,2,3,7,8,15,16,17,20,21,31,32,33,47,48,63,64,65,96,127,128,129,257]{for distribution in 0..7{case(&mut out,kind,length,seed,distribution,0)?;}}}}for kind in [0,4,5,6,8]{for length in [511,1024,2001,4097]{for distribution in [0,5]{case(&mut out,kind,length,1,distribution,0)?;}}}for kind in [0,4,5,8]{for length in [21,33,65,129]{for mode in 1..4{case(&mut out,kind,length,2,0,mode)?;}}}for length in [0,1,2,21,33,1024]{case(&mut out,9,length,1,0,0)?;}Ok(())}
